#include <stdio.h>
#include <stdlib.h>

#define MAX_EDGES 1000005
#define MAX_U 10005
#define MAX_N 1005

int head[MAX_U];
int to[MAX_EDGES];
int nxt[MAX_EDGES];
int edge_cnt = 0;

void add_edge(int u, int card) {
    to[edge_cnt] = card;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

int hits[MAX_N];
int winner[MAX_N];

int main() {
    int N, K, U;
    if (scanf("%d %d %d", &N, &K, &U) != 3) {
        return 0;
    }

    for (int i = 1; i <= U; ++i) {
        head[i] = -1;
    }

    for (int i = 1; i <= N; ++i) {
        for (int j = 0; j < K; ++j) {
            int num;
            scanf("%d", &num);
            add_edge(num, i);
        }
    }

    int found_winner = 0;

    for (int step = 0; step < U; ++step) {
        int drawn;
        scanf("%d", &drawn);

        if (found_winner) {
            continue;
        }

        for (int e = head[drawn]; e != -1; e = nxt[e]) {
            int card = to[e];
            hits[card]++;
            if (hits[card] == K) {
                winner[card] = 1;
                found_winner = 1;
            }
        }
    }

    int first = 1;
    for (int i = 1; i <= N; ++i) {
        if (winner[i]) {
            if (!first) {
                putchar(' ');
            }
            printf("%d", i);
            first = 0;
        }
    }
    putchar('\n');

    return 0;
}
